//! Starflight — an orbital strike for Horizon.
//!
//! An independent reimplementation of the mechanics described by *The Shooting
//! Star [Demo]* (All Rights Reserved). No upstream code or assets are used.
//!
//! Every hook signature, event field and host method below was read from the
//! mod API generated by `horizon-rust/horizon@69ab572`, which this crate is
//! compiled against — nothing here is guessed.

#![forbid(unsafe_code)]

pub mod strike;

use std::sync::Mutex;

use mod_api::{
    BlockEdit, BlockRun, Flow, Hooks, HostSide, Identifier, LogicalSide, RightClickItemEvent,
    ServerHost, ServerTickEvent,
};

/// The item whose right-click calls a strike down.
pub const STRIKE_ITEM: &str = "starflight:orbital_rocket";

/// Radius of the carve, in blocks.
const STRIKE_RADIUS: f64 = 16.0;
/// Blocks carved above the target.
const CARVE_ABOVE: i32 = 24;
/// Blocks carved below the target.
const CARVE_BELOW: i32 = 16;
/// The dimension the strike carves in.
const DIMENSION: &str = "minecraft:overworld";
/// The block every carve writes.
const CARVE_BLOCK: &str = "minecraft:air";

/// The mod.
///
/// The hooks take `&self` and the mod must be `Sync`, so the live strikes sit
/// behind a `Mutex`. A poisoned lock means a previous tick panicked; that is
/// handled by doing nothing rather than propagating a panic into the game.
#[derive(Default)]
pub struct Starflight {
    active: Mutex<Vec<strike::Strike>>,
}

#[mod_api::horizon_mod]
impl Hooks for Starflight {
    /// Right-clicking with the rocket item calls a strike onto the aimed block.
    fn right_click_item(
        &self,
        host: HostSide<'_>,
        event: &mut RightClickItemEvent<'_>,
    ) -> Flow {
        // A client's copy would act on a world it does not own.
        if event.click.side != LogicalSide::Server {
            return Flow::Continue;
        }
        let HostSide::Server(server) = host else {
            return Flow::Continue;
        };

        // `ItemKey` is opaque, so the id is resolved through the host and compared.
        let Ok(id) = Identifier::parse(STRIKE_ITEM) else {
            return Flow::Continue;
        };
        let Some(wanted) = server.item_key(&id) else {
            return Flow::Continue;
        };
        if event.click.stack.item() != wanted {
            return Flow::Continue;
        }

        let [x, y, z] = event.click.pos;
        let queued = strike::Strike::new(
            f64::from(x) + 0.5,
            f64::from(z) + 0.5,
            STRIKE_RADIUS,
            y - CARVE_BELOW,
            y + CARVE_ABOVE,
        );

        match queued {
            Ok(s) => {
                if let Ok(mut active) = self.active.lock() {
                    active.push(s);
                }
                Flow::Cancel
            }
            Err(reason) => {
                // Out-of-range input is refused, never quietly clamped (D5).
                eprintln!("starflight: strike refused: {reason}");
                Flow::Continue
            }
        }
    }

    /// Advances every live strike by one tick, writing a budget of blocks.
    fn server_tick(&self, host: &mut dyn ServerHost, _event: &mut ServerTickEvent<'_>) {
        let Ok(mut active) = self.active.lock() else {
            return;
        };
        if active.is_empty() {
            return;
        }

        // One palette for the whole tick: every run writes the same block.
        let Some(air) = host.block_state_id(CARVE_BLOCK) else {
            eprintln!("starflight: {CARVE_BLOCK} is not a known block; dropping strikes");
            active.clear();
            return;
        };

        let mut finished = Vec::new();
        for (index, s) in active.iter_mut().enumerate() {
            let positions = s.tick();
            if positions.is_empty() {
                if s.phase() == strike::Phase::Done {
                    finished.push(index);
                }
                continue;
            }

            let edit = BlockEdit {
                palette: vec![air],
                filters: Vec::new(),
                runs: positions
                    .iter()
                    .map(|p| BlockRun {
                        x: p.x,
                        y: p.y,
                        z: p.z,
                        height: 1,
                        surface: None,
                        block: 0,
                        only: None,
                    })
                    .collect(),
            };

            if let Err(reason) = host.edit_blocks(DIMENSION, &edit) {
                // The edit is all-or-nothing, so a refusal leaves the world
                // untouched; abandon the strike instead of retrying forever.
                eprintln!("starflight: block edit refused: {reason}");
                finished.push(index);
            }
        }

        for index in finished.into_iter().rev() {
            active.swap_remove(index);
        }
    }
}
